model:
rachana: 1
sutra: ir-vol-cube
version: 1
description: 
match: { kind: ir-vol-cube, priority: 10 }
title: { pill: "Market data · Swaption volatility cube", id: "$.CUBE_ID" }
strip:
  - { label: "Currency", bind: "$.CURRENCY" }
  - { label: "Model", bind: "$.MODEL" }
  - { label: "1Y×10Y", bind: "$.V_1Y_10Y", fmt: "price2", emphasis: true }
  - { label: "5Y×5Y", bind: "$.V_5Y_5Y", fmt: "price2" }
panels:
  - id: surface
    kind: surface
    title: "Normal vols by expiry × tenor (bp)"
    key: "F4"
    code: "SURF"
    rows: "$.GRID"
    y: "EXPIRY"
    columns:
      - { label: "1Y", bind: "@.T_1Y", fmt: "price2" }
      - { label: "2Y", bind: "@.T_2Y", fmt: "price2" }
      - { label: "5Y", bind: "@.T_5Y", fmt: "price2" }
      - { label: "10Y", bind: "@.T_10Y", fmt: "price2" }
      - { label: "30Y", bind: "@.T_30Y", fmt: "price2" }
  - id: grid
    kind: table
    title: "ATM normal vols (bp)"
    key: "F2"
    rows: "$.GRID"
    columns:
      - { label: "Expiry", bind: "@.EXPIRY" }
      - { label: "1Y", bind: "@.T_1Y", fmt: "price2" }
      - { label: "2Y", bind: "@.T_2Y", fmt: "price2" }
      - { label: "5Y", bind: "@.T_5Y", fmt: "price2" }
      - { label: "10Y", bind: "@.T_10Y", fmt: "price2" }
      - { label: "30Y", bind: "@.T_30Y", fmt: "price2" }
  - id: row10y
    kind: line
    title: "10Y tenor by expiry"
    area: right
    phone: { tier: "glance", from: "fragment" }
    rows: "$.GRID"
    x: "EXPIRY"
    y: "T_10Y"
    fmt: "price2"
  - id: built
    kind: provenance
    title: "How this view was built"
    phone: { tier: "more", from: "fragment" }
keys: { F8: "impact", F9: "raw" }
